local RoyalCrestCarver = {}
local PRODUCTS = {
    simple_wooden_crest = { name = "Preprost lesen grb", woodCost = 2, paintCost = 1, time = 4, cost = 60, beauty = 25, prestige = 4, happiness = 1, description = "Preprost leseni grb za hišo." },
    painted_wooden_crest = { name = "Poslikan leseni grb", woodCost = 2, paintCost = 2, goldCost = 1, time = 7, cost = 180, beauty = 40, prestige = 10, happiness = 2, description = "Poslikan leseni grb za trgovce." },
    marble_relief_crest = { name = "Marmornat reliefa grb", marbleCost = 2, paintCost = 2, goldCost = 1, time = 10, cost = 460, beauty = 55, prestige = 18, happiness = 3, description = "Marmornat reliefa grb za plemiče." },
    silver_inlaid_crest = { name = "Srebrnovloženi grb", marbleCost = 2, silverCost = 2, goldCost = 1, paintCost = 1, time = 14, cost = 1100, beauty = 70, prestige = 30, happiness = 4, description = "Srebrnovloženi grb za visoke plemiče." },
    gold_leaf_crest = { name = "Zlatolistni grb", marbleCost = 3, goldCost = 2, silverCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 2400, beauty = 82, prestige = 45, happiness = 6, description = "Zlatolistni grb z draguljem za visoko plemstvo." },
    royal_grand_crest = { name = "Kraljevski veliki grb", marbleCost = 4, goldCost = 3, silverCost = 2, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 26, cost = 5500, beauty = 95, prestige = 75, happiness = 13, description = "Veliki kraljevski grb z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    crest_workshop = { name = "Grbovna delavnica", cost = { gold = 260, wood = 120, stone = 120, paint = 6 }, upkeep = 6, qualityBonus = 5 },
    heraldic_loft = { name = "Heraldikova podstrešje", cost = { gold = 950, wood = 260, stone = 280, marble = 4, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_carver_atelier = { name = "Mojstrski rezbarski atelje", cost = { gold = 2600, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 60, qualityBonus = 30 },
    royal_heraldry_palace = { name = "Kraljevska grboslovna palača", cost = { gold = 11000, wood = 600, stone = 800, gold = 70, jewel = 18 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
RoyalCrestCarver.woodStock = 14; RoyalCrestCarver.marbleStock = 12; RoyalCrestCarver.paintStock = 12; RoyalCrestCarver.silverStock = 6; RoyalCrestCarver.goldStock = 6; RoyalCrestCarver.jewelStock = 4; RoyalCrestCarver.pearlStock = 4
RoyalCrestCarver.productStock = {}; RoyalCrestCarver.buildings = {}; RoyalCrestCarver.maker = nil; RoyalCrestCarver.activeMaking = {}; RoyalCrestCarver.totalProducts = 0; RoyalCrestCarver.dayTimer = 0
function RoyalCrestCarver.init() RoyalCrestCarver.woodStock=14; RoyalCrestCarver.marbleStock=12; RoyalCrestCarver.paintStock=12; RoyalCrestCarver.silverStock=6; RoyalCrestCarver.goldStock=6; RoyalCrestCarver.jewelStock=4; RoyalCrestCarver.pearlStock=4; RoyalCrestCarver.productStock={}; RoyalCrestCarver.buildings={}; RoyalCrestCarver.maker=nil; RoyalCrestCarver.activeMaking={}; RoyalCrestCarver.totalProducts=0; RoyalCrestCarver.dayTimer=0; print("[RoyalCrestCarver] Royal Crest Carver System initialized (6 products, 4 buildings)") end
function RoyalCrestCarver.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RoyalCrestCarver.maker={name=n or ("Grbovar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grbovar najet: %s (spretnost: %d)",RoyalCrestCarver.maker.name,s),"success") end; return true end
function RoyalCrestCarver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RoyalCrestCarver.build(id) local ok,e=RoyalCrestCarver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RoyalCrestCarver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RoyalCrestCarver.getQualityBonus() local b=0; for _,bd in ipairs(RoyalCrestCarver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RoyalCrestCarver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and RoyalCrestCarver.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.marbleCost and RoyalCrestCarver.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.paintCost and RoyalCrestCarver.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and RoyalCrestCarver.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RoyalCrestCarver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RoyalCrestCarver.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RoyalCrestCarver.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RoyalCrestCarver.buildings==0 then return false,"Potrebna grbovna delavnica" end; if not RoyalCrestCarver.maker then return false,"Potreben grbovar" end; return true end
function RoyalCrestCarver.make(pt,qty) qty=qty or 1; local ok,e=RoyalCrestCarver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then RoyalCrestCarver.woodStock=RoyalCrestCarver.woodStock-d.woodCost*qty end; if d.marbleCost then RoyalCrestCarver.marbleStock=RoyalCrestCarver.marbleStock-d.marbleCost*qty end; if d.paintCost then RoyalCrestCarver.paintStock=RoyalCrestCarver.paintStock-d.paintCost*qty end; if d.silverCost then RoyalCrestCarver.silverStock=RoyalCrestCarver.silverStock-d.silverCost*qty end; if d.goldCost then RoyalCrestCarver.goldStock=RoyalCrestCarver.goldStock-d.goldCost*qty end; if d.jewelCost then RoyalCrestCarver.jewelStock=RoyalCrestCarver.jewelStock-d.jewelCost*qty end; if d.pearlCost then RoyalCrestCarver.pearlStock=RoyalCrestCarver.pearlStock-d.pearlCost*qty end; local t=d.time; if RoyalCrestCarver.maker then t=math.max(1,t-math.floor(RoyalCrestCarver.maker.skill/12)) end; table.insert(RoyalCrestCarver.activeMaking,{id="crest_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbarjenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RoyalCrestCarver.completeMaking(m) local q=1.0+(RoyalCrestCarver.getQualityBonus()/100); if RoyalCrestCarver.maker then q=q+(RoyalCrestCarver.maker.skill/140) end; q=math.min(2.5,q); RoyalCrestCarver.productStock[m.productType]=(RoyalCrestCarver.productStock[m.productType] or 0)+m.quantity; RoyalCrestCarver.totalProducts=RoyalCrestCarver.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RoyalCrestCarver.maker then RoyalCrestCarver.maker.itemsMade=RoyalCrestCarver.maker.itemsMade+m.quantity; if math.random()<0.25 then RoyalCrestCarver.maker.skill=math.min(100,RoyalCrestCarver.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grb izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crest.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function RoyalCrestCarver.update(dt) if not _G.state then return end; RoyalCrestCarver.dayTimer=RoyalCrestCarver.dayTimer+dt; if RoyalCrestCarver.dayTimer>=30 then RoyalCrestCarver.dayTimer=0; for i=#RoyalCrestCarver.activeMaking,1,-1 do local m=RoyalCrestCarver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RoyalCrestCarver.completeMaking(m); table.remove(RoyalCrestCarver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RoyalCrestCarver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RoyalCrestCarver.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RoyalCrestCarver.getStats() return {woodStock=RoyalCrestCarver.woodStock,marbleStock=RoyalCrestCarver.marbleStock,paintStock=RoyalCrestCarver.paintStock,silverStock=RoyalCrestCarver.silverStock,goldStock=RoyalCrestCarver.goldStock,jewelStock=RoyalCrestCarver.jewelStock,pearlStock=RoyalCrestCarver.pearlStock,productStock=RoyalCrestCarver.productStock,numBuildings=#RoyalCrestCarver.buildings,hasMaker=RoyalCrestCarver.maker~=nil,makerName=RoyalCrestCarver.maker and RoyalCrestCarver.maker.name or "—",makerSkill=RoyalCrestCarver.maker and RoyalCrestCarver.maker.skill or 0,activeMaking=#RoyalCrestCarver.activeMaking,totalProducts=RoyalCrestCarver.totalProducts} end
return RoyalCrestCarver
